<template><PageShell title="Incident Escalations" subtitle="Surface unresolved requests, repeated offer failures, and cases that have waited unusually long for operational resolution." icon="lucide:triangle-alert" eyebrow="Platform Executive"><div class="grid gap-3 sm:grid-cols-5"><Stat label="Needs review" :value="stats.total"/><Stat label="Critical" :value="stats.critical"/><Stat label="Multiple offer failures" :value="stats.multiple_failures"/><Stat label="Overdue" :value="stats.overdue"/><Stat label="Critical overdue" :value="stats.critical_overdue"/></div><section class="mt-6 overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div v-if="loading" class="py-20 text-center text-sm text-slate-400">Checking escalations...</div><div v-else-if="!items.length" class="py-20 text-center"><p class="font-black text-slate-700 dark:text-white/70">No escalated incidents right now</p><p class="mt-1 text-xs text-slate-400">This queue is driven by real unresolved and failed-offer conditions.</p></div><div v-else class="divide-y divide-base-300 dark:divide-white/5"><article v-for="i in items" :key="i.id" class="p-5"><div class="flex flex-wrap justify-between gap-3"><div><p class="font-black text-slate-800 dark:text-white/75">{{ i.reference_number }} · {{ i.category_name }}</p><p class="mt-1 text-xs text-slate-400">{{ i.address_text }}</p></div><div class="flex flex-wrap gap-1.5">
<span v-if="i.attention_level && i.attention_level!=='normal'" class="h-fit rounded-full px-2.5 py-1 text-[.65rem] font-black" :class="i.attention_level==='critical_overdue'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700'">{{ i.attention_level==='critical_overdue'?'Critical Overdue':'Overdue' }}</span>
<span class="h-fit rounded-full bg-red-100 px-2.5 py-1 text-[.65rem] font-black text-red-700">{{ i.severity }}</span>
</div></div><div class="mt-3 flex flex-wrap gap-2 text-xs"><span class="rounded-lg bg-base-200 px-2.5 py-1.5">{{ i.failed_offers }} failed offers</span><span class="rounded-lg bg-base-200 px-2.5 py-1.5">{{ i.candidate_count }} DSS candidates</span><span class="rounded-lg bg-base-200 px-2.5 py-1.5">Submitted {{ format(i.submitted_at) }}</span><span v-if="i.age_minutes!=null" class="rounded-lg bg-base-200 px-2.5 py-1.5">{{ ageLabel(i.age_minutes) }} unresolved</span></div></article></div></section></PageShell></template>
<script setup>import{defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformEscalations}from'@/services/adminCompletion';const items=ref([]),stats=ref({}),loading=ref(false);const Stat=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h('p',{class:'text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const format=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'—';const ageLabel=m=>{m=Number(m||0);if(m>=1440)return `${Math.floor(m/1440)}d ${Math.floor((m%1440)/60)}h`;if(m>=60)return `${Math.floor(m/60)}h ${m%60}m`;return `${m}m`};onMounted(async()=>{loading.value=true;try{const d=await fetchPlatformEscalations();items.value=d.items||[];stats.value=d.stats||{}}finally{loading.value=false}})</script>
